import{c as l,Q as o,j as s,g as t,n as e}from"./chunks/framework.DOi4mjdC.js";const a="/assets/%E5%AD%AA%E7%94%9F%E8%B0%83%E8%AF%95%E7%AE%80%E4%BB%8B.N_t-NKqy.png",h=JSON.parse('{"title":"概述","description":"","frontmatter":{},"headers":[{"level":1,"title":"概述","slug":"概述"}],"relativePath":"guide/编程指南/调试调优/概述.md","filePath":"guide/编程指南/调试调优/概述.md"}'),n={name:"guide/编程指南/调试调优/概述.md"};function p(d,r,i,c,g,w){return o(),s("div",null,[...r[0]||(r[0]=[t("h1",{id:"概述",tabindex:"-1"},[e("概述 "),t("a",{class:"header-anchor",href:"#概述","aria-label":'Permalink to "概述"'},"​")],-1),t("p",null,"Ascend C算子调试的整体方案如下：开发者通过调用Ascend C类库编写Ascend C算子Kernel侧源码，Kernel侧源码通过通用的GCC编译器进行编译，编译生成通用的CPU域的二进制，可以通过gdb通用调试工具等调试手段进行调试；Kernel侧源码通过毕昇编译器进行编译，编译生成NPU域的二进制文件，可使用printf/assert等接口进行数据打印，也可通过仿真打点图或者Profiling工具进行上板数据采集等方式进行调试。",-1),t("p",null,[t("img",{src:a,alt:""})],-1),t("p",null,"具体的调试调优方法和使用的工具列表如下：",-1),t("p",null,[t("strong",null,"表 1"),e(" 调试调优方法和使用的工具列表")],-1),t("p",null,'<table><thead align="left"><tr><th class="cellrowborder" valign="top" width="10.41104110411041%"><p>分类</p> </th> <th class="cellrowborder" valign="top" width="15.541554155415543%"><p>子分类</p> </th> <th class="cellrowborder" valign="top" width="74.04740474047404%"><p>方法</p> </th> </tr> </thead> <tbody><tr><td class="cellrowborder" rowspan="5" valign="top" width="10.41104110411041%"><p>功能调试</p> </td> <td class="cellrowborder" valign="top" width="15.541554155415543%"><p>CPU域孪生调试</p> </td> <td class="cellrowborder" valign="top" width="74.04740474047404%"><p><strong>孪生调试</strong>：相同的算子代码可以在CPU域调试精度，NPU域调试性能。在CPU域可以进行gdb调试、使用printf命令打印。</p> </td> </tr> <tr><td class="cellrowborder" rowspan="4" valign="top"><p>NPU域上板调试</p> </td> <td class="cellrowborder" valign="top"><p><strong>printf/assert：</strong>printf主要用于打印标量和字符串信息；assert主要用于在代码中设置检查点，当某个条件不满足时，程序会立即终止并报错。</p> </td> </tr> <tr><td class="cellrowborder" valign="top"><p><strong>DumpTensor：</strong>使用DumpTensor接口打印指定Tensor的数据，只支持SIMD编程场景。</p> </td> </tr> <tr><td class="cellrowborder" valign="top"><p><strong>上板调试工具：</strong>使用msDebug工具调试NPU侧运行的算子程序，在真实的硬件环境中，对算子的输入输出进行测试，以验证算子的功能是否正确。具体功能包括断点设置、打印变量和内存、单步调试、中断运行等。当前SIMT编程场景暂不支持。</p> </td> </tr> <tr><td class="cellrowborder" valign="top"><p><strong>内存检测工具：</strong>使用msSanitizer工具进行内存检测，可以检测并报告算子运行中对外部存储（Global Memory）和内部存储（Local Memory）的越界及未对齐等内存访问异常。</p> </td> </tr> <tr><td class="cellrowborder" valign="top" width="10.41104110411041%"><p>性能调优</p> </td> <td class="cellrowborder" valign="top" width="15.541554155415543%"><p>-</p> </td> <td class="cellrowborder" valign="top" width="74.04740474047404%"><p><strong>msprof工具：</strong></p> <p>msProf工具用于采集和分析运行在<span>AI处理器</span>上算子的关键性能指标，用户可根据输出的性能数据，快速定位算子的软、硬件性能瓶颈，提升算子性能的分析效率。</p> <p>当前支持基于不同运行模式（上板或仿真）和不同文件形式（可执行文件或算子二进制<strong>.o</strong>文件）进行性能数据的采集和自动解析。</p> </td> </tr> </tbody> </table>',-1)])])}const m=l(n,[["render",p]]);export{h as __pageData,m as default};
